const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{height:100%;min-height:0;min-width:0;overflow:hidden;color:var(--ink)}\n.rp{box-sizing:border-box;height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px;padding:10px;font-size:13px;line-height:1.3;color:var(--ink)}\n.rp *{box-sizing:border-box}\n.rp button{font:inherit;cursor:pointer}\n.card[data-size=\"3x3\"] .rp{padding:8px;gap:6px}\n\n.top{display:none}\n.card[data-size=\"3x6\"] .top,.card[data-size=\"6x6\"] .top{display:flex;flex-direction:column;gap:2px}\n.ttl{font-size:16px;font-weight:700}\n.sum{font-size:11px;color:var(--muted)}\n\n.head{display:flex;gap:6px;align-items:center;min-width:0;flex:none}\n.tabs{display:flex;gap:2px;flex:1 1 auto;min-width:0;padding:2px;border-radius:999px;background:var(--soft)}\n.tab{flex:1 1 auto;min-width:0;border:0;border-radius:999px;background:transparent;color:var(--muted);font-size:11px;padding:5px 4px;white-space:nowrap}\n.tab .n{margin-left:3px;font-size:10px;opacity:.85}\n.tab.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.card[data-size=\"6x3\"] .tab,.card[data-size=\"6x6\"] .tab,.card[data-size=\"3x6\"] .tab{font-size:12px;padding:6px 8px}\n.card[data-size=\"6x3\"] .tabs,.card[data-size=\"6x6\"] .tabs{flex:0 1 auto}\n.card[data-size=\"6x3\"] .head,.card[data-size=\"6x6\"] .head{justify-content:space-between}\n.add{flex:none;display:inline-flex;align-items:center;justify-content:center;gap:4px;height:28px;min-width:28px;padding:0 8px;border:0;border-radius:999px;background:var(--accent);color:var(--on-accent);font-weight:600}\n.add .plus{font-size:16px;line-height:1}\n.add-l{display:none;font-size:12px}\n.card:not([data-size=\"3x3\"]) .add-l{display:inline}\n\n.notice{flex:none;padding:6px 8px;border-radius:8px;border:1px solid var(--accent);background:var(--soft);font-size:12px}\n.hint{flex:none;display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:11px;color:var(--muted)}\n.link{border:0;background:none;padding:0;color:var(--ink);text-decoration:underline;font-size:11px}\n\n.list{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:grid;grid-template-columns:minmax(0,1fr);gap:6px;align-content:start}\n.card[data-size=\"6x3\"] .list,.card[data-size=\"6x6\"] .list{grid-template-columns:repeat(2,minmax(0,1fr))}\n.book{appearance:none;display:flex;flex-direction:column;gap:5px;min-width:0;width:100%;text-align:left;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--soft);color:var(--ink)}\n.book.stale{border-left:4px solid var(--accent-alt)}\n.book:focus-visible,.tab:focus-visible,.add:focus-visible,.cta:focus-visible,.link:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.b-top{display:flex;align-items:baseline;gap:6px;min-width:0}\n.b-title{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;font-size:13px}\n.b-pct{flex:none;font-weight:700;font-variant-numeric:tabular-nums;font-size:13px}\n.bar{display:block;height:6px;border-radius:999px;background:var(--line);overflow:hidden}\n.bar.big{height:10px}\n.fill{display:block;height:100%;border-radius:999px;background:var(--accent)}\n.b-meta{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;font-size:10.5px;color:var(--muted)}\n.b-pages{flex:none;white-space:nowrap}\n.b-when{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.late{flex:none;display:inline-block;margin-left:4px;padding:0 6px;border:1px solid var(--accent-alt);border-radius:999px;color:var(--ink);font-weight:600;font-size:10.5px;white-space:nowrap}\n.b-meta .late{margin-left:0}\n.b-date{display:none;font-size:11px;color:var(--muted)}\n.card[data-size=\"3x6\"] .b-date,.card[data-size=\"6x6\"] .b-date{display:block}\n.card[data-size=\"3x6\"] .book,.card[data-size=\"6x6\"] .book{padding:10px 12px;gap:6px}\n.card[data-size=\"3x6\"] .bar,.card[data-size=\"6x6\"] .bar{height:8px}\n.card[data-size=\"3x6\"] .b-meta,.card[data-size=\"6x6\"] .b-meta{font-size:11.5px}\n.card[data-size=\"6x6\"] .rp{padding:14px;gap:10px}\n.card[data-size=\"6x6\"] .b-title,.card[data-size=\"6x6\"] .b-pct{font-size:14px}\n\n.empty{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;color:var(--muted);font-size:12px;padding:6px}\n.cta{border:0;border-radius:999px;background:var(--accent);color:var(--on-accent);padding:7px 14px;font-weight:600;font-size:12px}\n\n.detail{display:flex;flex-direction:column;gap:8px;min-width:0}\n.d-pct{font-size:28px;font-weight:700;line-height:1.1;font-variant-numeric:tabular-nums}\n.d-line{display:flex;flex-wrap:wrap;align-items:center;gap:4px;font-size:12px;color:var(--ink);min-width:0;overflow-wrap:anywhere}\n.d-err{padding:6px 8px;border:1px solid var(--accent-alt);border-radius:8px;font-size:12px;color:var(--ink)}\n.card[data-size=\"3x3\"] .d-pct{font-size:22px}\n";
function parseDay(s){
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s||''));
  if(!m)return null;
  return new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));
}
function daysSince(s,today){
  const a=parseDay(s),b=parseDay(today);
  if(!a||!b)return null;
  return Math.round((b.getTime()-a.getTime())/86400000);
}
function whenText(days){
  if(days===null||days===undefined)return '';
  if(days<=0)return '今天读过';
  if(days===1)return '昨天读过';
  return days+' 天前读';
}
function staleLimit(s){
  const n=Number(s&&s.staleDays);
  return Number.isInteger(n)&&n>=1?n:14;
}
function cleanBooks(s){
  const list=s&&Array.isArray(s.books)?s.books:[];
  return list.filter(b=>b&&b.id&&b.title&&Number(b.total)>0).map(b=>{
    const total=Number(b.total);
    const cur=Math.min(total,Math.max(0,Number(b.current)||0));
    return {...b,total:total,current:cur};
  });
}
function settle(b,today){
  const nb={...b};
  if(nb.current>=nb.total){
    nb.current=nb.total;
    nb.lastRead=nb.lastRead||today;
    nb.finishedAt=nb.finishedAt||nb.lastRead;
  }else{
    nb.finishedAt=null;
  }
  return nb;
}
function checkDate(v,today){
  const d=daysSince(v,today);
  if(d===null)return '请选择阅读日期';
  if(d<0)return '阅读日期不能晚于今天';
  return '';
}
function toInt(v,fallback){
  if(v===''||v===null||v===undefined)return fallback;
  return Number(v);
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,editor,panel}=ctx;
  const today=day();
  const books=cleanBooks(state);
  const limit=staleLimit(state);

  const infoOf=(b)=>{
    const done=!!b.finishedAt;
    const ref=b.lastRead||b.addedAt||today;
    const idle=daysSince(ref,today);
    const readDays=b.lastRead?daysSince(b.lastRead,today):null;
    return {
      b:b,
      done:done,
      pct:Math.min(100,Math.floor(percent(b.current,b.total))),
      idle:idle===null?0:idle,
      readDays:readDays,
      stale:!done&&idle!==null&&idle>=limit
    };
  };
  const infos=books.map(infoOf);

  const go=(view,extra)=>{
    Object.assign(ui,{view:view,error:'',confirmDel:null,notice:''},extra||{});
    redraw();
  };
  const fail=(e)=>{
    ui.error='保存失败：'+((e&&e.message)||'请稍后再试');
    redraw();
  };
  const allBooks=(s)=>Array.isArray(s.books)?s.books:[];
  const patch=(id,fn)=>(s)=>({...s,books:allBooks(s).map(x=>x&&x.id===id?fn(x):x)});

  const finishNow=(b)=>{
    update(patch(b.id,x=>settle({...x,current:Number(x.total),lastRead:today,finishedAt:null},today)))
      .then(()=>go('list',{tab:'history',sel:null,notice:'《'+b.title+'》读完了，已放进历史记录'}))
      .catch(fail);
  };
  const removeBook=(b)=>{
    update(s=>({...s,books:allBooks(s).filter(x=>!(x&&x.id===b.id))}))
      .then(()=>go('list',{sel:null,notice:'已删除《'+b.title+'》'}))
      .catch(fail);
  };

  const bar=(pct,big)=>{
    const fill=el('i',{class:'fill'});
    fill.style.width=pct+'%';
    return el('span',{class:'bar'+(big?' big':'')},fill);
  };

  const row=(i)=>{
    const b=i.b;
    let right;
    if(i.done)right=el('span',{class:'b-when'},'读完于 '+b.finishedAt);
    else if(i.stale)right=el('span',{class:'late'},i.idle+' 天未读');
    else if(!b.lastRead)right=el('span',{class:'b-when'},'还没开始');
    else right=el('span',{class:'b-when'},whenText(i.readDays));
    const kids=[
      el('span',{class:'b-top'},
        el('span',{class:'b-title'},b.title),
        el('span',{class:'b-pct'},i.done?'已读完':i.pct+'%')),
      bar(i.pct,false),
      el('span',{class:'b-meta'},
        el('span',{class:'b-pages'},i.done?('共 '+b.total+' 页'):(b.current+'/'+b.total+' 页')),
        right)
    ];
    if(!i.done)kids.push(el('span',{class:'b-date'},b.lastRead?('最近阅读 '+b.lastRead):'还没有阅读记录'));
    return el('button',{
      type:'button',
      class:'book'+(i.stale?' stale':'')+(i.done?' done':''),
      'aria-label':b.title+'，'+(i.done?'已读完':'进度 '+i.pct+'%'),
      onclick:()=>go('detail',{sel:b.id})
    },...kids);
  };


  const listView=()=>{
    const tab=ui.tab||'reading';
    const reading=infos.filter(i=>!i.done);
    const stale=reading.filter(i=>i.stale);
    const hist=infos.filter(i=>i.done);
    let shown;
    if(tab==='history'){
      shown=hist.slice().sort((a,b)=>String(b.b.finishedAt).localeCompare(String(a.b.finishedAt)));
    }else{
      shown=(tab==='stale'?stale:reading).slice().sort((a,b)=>b.idle-a.idle||String(a.b.title).localeCompare(String(b.b.title)));
    }
    const tabs=[['reading','在读',reading.length],['stale','久未读',stale.length],['history','历史',hist.length]];
    const tabBar=el('div',{class:'tabs',role:'tablist'},...tabs.map(t=>el('button',{
      type:'button',role:'tab',
      class:'tab'+(tab===t[0]?' on':''),
      'aria-selected':tab===t[0]?'true':'false',
      onclick:()=>{ui.tab=t[0];ui.notice='';redraw();}
    },t[1],el('span',{class:'n'},String(t[2])))));
    const addBtn=el('button',{
      type:'button',class:'add','aria-label':'添加书籍',
      onclick:()=>go('add',{draft:{title:'',total:'',current:'',lastRead:''}})
    },el('span',{class:'plus'},'+'),el('span',{class:'add-l'},'添加'));

    const kids=[];
    kids.push(el('div',{class:'top'},
      el('div',{class:'ttl'},'阅读进度'),
      el('div',{class:'sum'},'在读 '+reading.length+' 本 · 久未读 '+stale.length+' 本 · 已读完 '+hist.length+' 本')));
    kids.push(el('div',{class:'head'},tabBar,addBtn));
    if(ui.notice)kids.push(el('div',{class:'notice',role:'status'},ui.notice));
    if(tab==='stale'){
      kids.push(el('div',{class:'hint'},
        el('span',{},'超过 '+limit+' 天没读算久未读'),
        el('button',{type:'button',class:'link',onclick:()=>go('settings',{draft:{staleDays:String(limit)}})},'修改')));
    }
    if(shown.length){
      kids.push(el('div',{class:'list'},...shown.map(row)));
    }else{
      let msg='';
      let cta=null;
      if(tab==='history')msg='读完的书会放进这里';
      else if(tab==='stale')msg=reading.length?'没有超过 '+limit+' 天没读的书':'还没有在读的书';
      else{
        msg=hist.length?'没有在读的书了':'还没有记录任何书';
        cta=el('button',{type:'button',class:'cta',onclick:()=>go('add',{draft:{title:'',total:'',current:'',lastRead:''}})},'添加一本书');
      }
      kids.push(el('div',{class:'empty'},...[el('div',{},msg),cta].filter(Boolean)));
    }
    return el('div',{class:'rp'},...kids);
  };

  const detailView=(i)=>{
    const b=i.b;
    const lines=[];
    lines.push(el('div',{class:'d-line'},'已读 '+b.current+' / '+b.total+' 页'+(i.done?'':'，还剩 '+(b.total-b.current)+' 页')));
    if(i.done){
      lines.push(el('div',{class:'d-line'},'读完于 '+b.finishedAt));
    }else{
      lines.push(el('div',{class:'d-line'},...[
        el('span',{},b.lastRead?('最近阅读 '+b.lastRead+' · '+whenText(i.readDays)):'还没有阅读记录'),
        i.stale?el('span',{class:'late'},i.idle+' 天未读'):null
      ].filter(Boolean)));
    }
    if(ui.error)lines.push(el('div',{class:'d-err',role:'alert'},'出错了：'+ui.error));
    const body=el('div',{class:'detail'},
      el('div',{class:'d-pct'},i.done?'已读完':i.pct+'%'),
      bar(i.pct,true),
      ...lines);
    const confirming=ui.confirmDel===b.id;
    const del={
      label:confirming?'再点一次确认删除':'删除',
      onClick:()=>{
        if(confirming)removeBook(b);
        else{ui.confirmDel=b.id;redraw();}
      }
    };
    const edit={label:'编辑书名/总页数',onClick:()=>go('edit',{sel:b.id,draft:{title:b.title,total:String(b.total)}})};
    const actions=i.done?[
      {label:'移回在读',primary:true,onClick:()=>go('progress',{sel:b.id,draft:{current:'',lastRead:today}})},
      edit,del
    ]:[
      {label:'更新进度',primary:true,onClick:()=>go('progress',{sel:b.id,draft:{current:String(b.current),lastRead:today}})},
      {label:'标记读完',onClick:()=>finishNow(b)},
      edit,del
    ];
    return panel({title:b.title,body:body,actions:actions,onBack:()=>go('list',{sel:null})});
  };


  const addForm=()=>{
    const draft=ui.draft||(ui.draft={title:'',total:'',current:'',lastRead:''});
    return editor({
      title:'添加书籍',draft:draft,submitLabel:'保存',
      fields:[
        {key:'title',label:'书名',type:'text',required:true,placeholder:'例如：三体'},
        {key:'total',label:'总页数',type:'number',required:true,min:1,step:1,placeholder:'例如：320'},
        {key:'current',label:'当前页码（没开始可留空）',type:'number',min:0,step:1,placeholder:'默认 0'},
        {key:'lastRead',label:'最近阅读日期（没开始可留空）',type:'date'}
      ],
      onBack:()=>go('list'),
      onSave:(v)=>{
        const title=String(v.title||'').trim();
        const total=Number(v.total);
        const cur=toInt(v.current,0);
        const lr=String(v.lastRead||'');
        if(!title)return '请填写书名';
        if(!Number.isInteger(total)||total<1)return '总页数请填 1 以上的整数';
        if(!Number.isInteger(cur)||cur<0||cur>total)return '当前页码需在 0 到总页数之间';
        if(lr){const e=checkDate(lr,today);if(e)return e;}
        const nb=settle({id:uid(),title:title,total:total,current:cur,lastRead:lr||(cur>0?today:''),addedAt:today,finishedAt:null},today);
        return commit(
          s=>({...s,books:[...allBooks(s),nb]}),
          {...ui,view:'list',draft:null,error:'',sel:null,tab:nb.finishedAt?'history':'reading',
            notice:nb.finishedAt?'《'+title+'》已读完，放进了历史记录':''}
        );
      }
    });
  };

  const progressForm=(i)=>{
    const b=i.b;
    const draft=ui.draft||(ui.draft={current:i.done?'':String(b.current),lastRead:today});
    return editor({
      title:i.done?'移回在读':'更新进度',draft:draft,submitLabel:'保存',
      fields:[
        {key:'current',label:i.done?'重新读到第几页（小于 '+b.total+'）':'当前页码（共 '+b.total+' 页，读到最后一页即读完）',type:'number',required:true,min:0,max:b.total,step:1},
        {key:'lastRead',label:'阅读日期',type:'date',required:true}
      ],
      onBack:()=>go('detail'),
      onSave:(v)=>{
        const c=toInt(v.current,NaN);
        const lr=String(v.lastRead||'');
        if(!Number.isInteger(c)||c<0||c>b.total)return '当前页码需在 0 到 '+b.total+' 之间';
        const e=checkDate(lr,today);
        if(e)return e;
        if(i.done&&c>=b.total)return '要移回在读，请填小于 '+b.total+' 的页码';
        const finished=c>=b.total;
        return commit(
          patch(b.id,x=>settle({...x,current:c,lastRead:lr,finishedAt:null},today)),
          {...ui,view:finished?'list':'detail',draft:null,error:'',sel:finished?null:b.id,
            tab:finished?'history':(i.done?'reading':(ui.tab||'reading')),
            notice:finished?'《'+b.title+'》读完了，已放进历史记录':''}
        );
      }
    });
  };

  const editForm=(i)=>{
    const b=i.b;
    const draft=ui.draft||(ui.draft={title:b.title,total:String(b.total)});
    return editor({
      title:'编辑书籍',draft:draft,submitLabel:'保存',
      fields:[
        {key:'title',label:'书名',type:'text',required:true},
        {key:'total',label:'总页数',type:'number',required:true,min:1,step:1}
      ],
      onBack:()=>go('detail'),
      onSave:(v)=>{
        const title=String(v.title||'').trim();
        const total=Number(v.total);
        if(!title)return '请填写书名';
        if(!Number.isInteger(total)||total<1)return '总页数请填 1 以上的整数';
        if(total<b.current)return '总页数不能小于已读的 '+b.current+' 页，请先更新进度';
        return commit(
          patch(b.id,x=>settle({...x,title:title,total:total},today)),
          {...ui,view:'detail',draft:null,error:'',sel:b.id}
        );
      }
    });
  };

  const settingsForm=()=>{
    const draft=ui.draft||(ui.draft={staleDays:String(limit)});
    return editor({
      title:'久未读设置',draft:draft,submitLabel:'保存',
      fields:[{key:'staleDays',label:'超过多少天没读，算久未读',type:'number',required:true,min:1,max:365,step:1}],
      onBack:()=>go('list'),
      onSave:(v)=>{
        const n=Number(v.staleDays);
        if(!Number.isInteger(n)||n<1||n>365)return '请填 1 到 365 之间的整数天数';
        return commit(s=>({...s,staleDays:n}),{...ui,view:'list',draft:null,error:'',tab:'stale',notice:''});
      }
    });
  };

  let v=ui.view||'list';
  const sel=infos.find(i=>i.b.id===ui.sel);
  if((v==='detail'||v==='progress'||v==='edit')&&!sel)v='list';
  if(v==='add')root.append(addForm());
  else if(v==='settings')root.append(settingsForm());
  else if(v==='progress')root.append(progressForm(sel));
  else if(v==='edit')root.append(editForm(sel));
  else if(v==='detail')root.append(detailView(sel));
  else root.append(listView());
